	public IEnumerable<SnoPower> GetClassSpecificPowers(HeroClass heroClass)
	{
		return classSpecificPowers.Value[heroClass];
	}

	public IEnumerable<SnoPower> GetLegendaryGemPowers()
	{
		return legendaryGemPowers.Value;
	}

	public IEnumerable<SnoPower> GetLegendaryItemPowers()
	{
		return legendaryItemPowers.Value;
	}

	public SnoPowerList()
	{
		classSpecificPowers = new Lazy<Dictionary<HeroClass, List<SnoPower>>>(BuildClassSpecificPowers);
		legendaryGemPowers = new Lazy<List<SnoPower>>(BuildLegendaryGemPowers);
		legendaryItemPowers = new Lazy<List<SnoPower>>(BuildLegendaryItemPowers);
	}

